// process.env values are always strings. Two environments a server might start with:
const staging = { NODE_ENV: 'production', PORT: '8080', DEBUG: 'false', DATABASE_URL: 'postgres://db:5432/shop' }
const broken = { NODE_ENV: 'production', PORT: '8080' }

function loadConfig(env) {
  // Fail fast: refuse to start without required settings
  const missing = ['DATABASE_URL', 'PORT'].filter((name) => !env[name])
  if (missing.length) throw new Error(`missing ${missing.join(', ')}`)
  return {
    port: Number(env.PORT),
    debug: Boolean(env.DEBUG), // bug: Boolean("false") is true
    databaseUrl: env.DATABASE_URL,
  }
}

console.log(loadConfig(staging))
try {
  loadConfig(broken)
} catch (err) {
  console.log('Refusing to start:', err.message)
}

// Percentage rollout: hash each user id to a stable bucket from 0 to 99.
function bucket(userId) {
  let hash = 2166136261 // FNV-1a, a simple, well-mixed string hash
  for (const ch of userId) {
    hash ^= ch.charCodeAt(0)
    hash = Math.imul(hash, 16777619) >>> 0
  }
  return hash % 100
}

function isEnabled(flag, userId) {
  if (flag.allowList.includes(userId)) return true // internal testers first
  return bucket(userId) < flag.percent
}

const newCheckout = { percent: 10, allowList: ['dev-ana'] }
const users = ['dev-ana', 'u-1001', 'u-1002', 'u-1003', 'u-1004', 'u-1005', 'u-1006']

for (const id of users) {
  console.log(id, 'bucket', bucket(id), isEnabled(newCheckout, id) ? 'NEW' : 'old')
}

// Latency in ms for 20 requests to POST /api/checkout
const latencies = [80, 95, 102, 110, 88, 120, 97, 105, 2900, 91, 99, 101, 93, 87, 115, 108, 3100, 96, 104, 90]

const average = latencies.reduce((sum, ms) => sum + ms, 0) / latencies.length

// Nearest-rank percentile: p percent of requests took this long or less
function percentile(values, p) {
  const sorted = [...values].sort((a, b) => a - b)
  const rank = Math.ceil((p / 100) * sorted.length)
  return sorted[rank - 1]
}

console.log('average:', Math.round(average), 'ms')
console.log('p50:', percentile(latencies, 50), 'ms')
console.log('p95:', percentile(latencies, 95), 'ms')

// Error budget: how much failure an availability SLO allows
function errorBudgetMinutes(slo, days) {
  return (1 - slo) * days * 24 * 60
}

